#include <stdio.h>

int main(void) {
    int amount, n;
    int last_coin[101];
    scanf("%d %d", &amount, &n);

    for (int i = 0; i < n; ++i) {
        scanf("%d", &last_coin[i]);
    }

    if (amount == 0) {
        puts("NONE");
    } else if (last_coin[amount] == -1) {
        puts("IMPOSSIBLE");
    } else {
        int first = 1;
        while (amount > 0) {
            int coin = last_coin[amount];
            printf("%s%d", first ? "" : " ", coin);
            first = 0;
            amount -= coin;
        }
        putchar('\n');
    }
    return 0;
}
